# owner: platform
"""Lay a roster out in seating rows."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

def by_last_name(student: Student) -> Tuple[str, str]:
    return (student.last_name, student.first_name)

def check_inputs(
    roster: List[Student], seats_per_row: int
) -> None:
    """Refuse an empty roster or a seat count below one."""
    if seats_per_row < 1:
        raise ValueError(f"bad seat count: {seats_per_row}")
    if not roster:
        raise ValueError("no students to seat")

def split_rows(
    roster: List[Student], seats_per_row: int
) -> List[List[Student]]:
    """Cut the sorted roster into one slice per row."""
    rows = []
    for start in range(0, len(roster), seats_per_row):
        rows.append(roster[start:start + seats_per_row])
    return rows

def format_rows(rows: List[List[Student]]) -> List[str]:
    lines = []
    for number, row in enumerate(rows, start=1):
        names = [student.display_name for student in row]
        lines.append(f"Row {number}: " + " | ".join(names))
    return lines

def seating_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One line of text per row, sorted by last name."""
    roster = sorted(students, key=by_last_name)
    check_inputs(roster, seats_per_row)
    return format_rows(split_rows(roster, seats_per_row))

