# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

SAMPLE = [
    ("Halloway", "Juno"),
    ("Dunmere", "Piet"),
    ("Varrow", "Ines"),
]

def roster_of(pairs):
    """Students from (last, first) pairs, ids in order."""
    return [
        Student(str(number), last, first, "A")
        for number, (last, first) in enumerate(pairs, 1)
    ]

class SeatingRowsTests(unittest.TestCase):
    def test_sorted_by_last_name(self):
        rows = seating_rows(roster_of(SAMPLE), 2)
        self.assertEqual(
            rows[0], "Row 1: Dunmere, Piet | Halloway, Juno"
        )

    def test_wraps_after_each_full_row(self):
        rows = seating_rows(roster_of(SAMPLE), 2)
        self.assertEqual(len(rows), 2)
        self.assertEqual(rows[1], "Row 2: Varrow, Ines")

    def test_first_name_breaks_ties(self):
        pairs = [("Lee", "Zoe"), ("Lee", "Amir")]
        rows = seating_rows(roster_of(pairs), 2)
        self.assertEqual(
            rows, ["Row 1: Lee, Amir | Lee, Zoe"]
        )

    def test_one_row_when_seats_cover_roster(self):
        rows = seating_rows(roster_of(SAMPLE), 10)
        self.assertEqual(len(rows), 1)

    def test_zero_seats_rejected(self):
        students = roster_of(SAMPLE)
        with self.assertRaises(ValueError):
            seating_rows(students, 0)

    def test_negative_seats_rejected(self):
        students = roster_of(SAMPLE)
        with self.assertRaises(ValueError):
            seating_rows(students, -3)

    def test_empty_roster_rejected(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
